-- Embedded additive baseline: all timestamps are UTC Unix seconds.
CREATE TABLE blobs(hash TEXT PRIMARY KEY NOT NULL CHECK(length(hash)=64), size INTEGER NOT NULL CHECK(size>=0), compressed_size INTEGER NOT NULL CHECK(compressed_size>=0), created_at INTEGER NOT NULL DEFAULT (unixepoch()), ref_count INTEGER NOT NULL DEFAULT 0 CHECK(ref_count>=0));
CREATE TABLE principals(id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL DEFAULT '', timezone TEXT NOT NULL DEFAULT 'UTC', language TEXT NOT NULL DEFAULT 'en', default_autonomy TEXT NOT NULL DEFAULT 'ask', created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE projects(id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL DEFAULT '', alias TEXT, description TEXT, roots TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(roots)), state TEXT NOT NULL DEFAULT 'active', vcs TEXT, settings TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(settings)), skill_groups TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(skill_groups)), principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE conversations(id TEXT PRIMARY KEY NOT NULL, channel TEXT, active_scope TEXT, persona TEXT, state TEXT NOT NULL DEFAULT 'active', principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE messages(id TEXT PRIMARY KEY NOT NULL, conversation_id TEXT REFERENCES conversations(id), role TEXT NOT NULL DEFAULT 'user', text TEXT NOT NULL DEFAULT '', attachments TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(attachments) AND json_type(attachments)='array'), language TEXT, reply_to TEXT REFERENCES messages(id), sent_at INTEGER NOT NULL DEFAULT (unixepoch()), user_timezone TEXT NOT NULL DEFAULT 'UTC', principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE plans(id TEXT PRIMARY KEY NOT NULL, kind TEXT NOT NULL DEFAULT 'macro', owner_task_id TEXT REFERENCES tasks(id), version INTEGER NOT NULL DEFAULT 1, state TEXT NOT NULL DEFAULT 'draft', principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE tasks(id TEXT PRIMARY KEY NOT NULL, project_id TEXT REFERENCES projects(id), code TEXT, level TEXT, request_card TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(request_card)), origin_conversation_id TEXT REFERENCES conversations(id), notification_policy TEXT, root_run_id TEXT REFERENCES runs(id), budget TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(budget)), derived_state TEXT NOT NULL DEFAULT 'pending', version INTEGER NOT NULL DEFAULT 1, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE plan_items(id TEXT PRIMARY KEY NOT NULL, code TEXT, plan_id TEXT REFERENCES plans(id), task_id TEXT REFERENCES tasks(id), title TEXT NOT NULL DEFAULT '', detail TEXT, state TEXT NOT NULL DEFAULT 'pending', priority INTEGER NOT NULL DEFAULT 0, agent_id TEXT REFERENCES agents(id), estimate TEXT, starts_at INTEGER, due_at INTEGER, version INTEGER NOT NULL DEFAULT 1, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE dependencies(id TEXT PRIMARY KEY NOT NULL, from_id TEXT NOT NULL, to_id TEXT NOT NULL, kind TEXT NOT NULL, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()), CHECK(from_id <> to_id));
CREATE TABLE milestones(id TEXT PRIMARY KEY NOT NULL, project_id TEXT REFERENCES projects(id), code TEXT, plan_id TEXT REFERENCES plans(id), title TEXT NOT NULL DEFAULT '', criteria TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(criteria)), target_at INTEGER, state TEXT NOT NULL DEFAULT 'pending', principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE requirements(id TEXT PRIMARY KEY NOT NULL, project_id TEXT REFERENCES projects(id), code TEXT, text TEXT NOT NULL DEFAULT '', origin_message_id TEXT REFERENCES messages(id), kind TEXT, priority INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'pending', version INTEGER NOT NULL DEFAULT 1, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE criteria(id TEXT PRIMARY KEY NOT NULL, code TEXT, requirement_id TEXT REFERENCES requirements(id), statement TEXT NOT NULL DEFAULT '', method TEXT, expected TEXT, impact_area TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE checks(id TEXT PRIMARY KEY NOT NULL, criterion_id TEXT REFERENCES criteria(id), definition TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(definition)), environment TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE evidence(id TEXT PRIMARY KEY NOT NULL, check_id TEXT REFERENCES checks(id), run_id TEXT REFERENCES runs(id), result TEXT, output_blob TEXT REFERENCES blobs(hash), code_version TEXT, fingerprints TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(fingerprints)), tool_call_id TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE assumptions(id TEXT PRIMARY KEY NOT NULL, text TEXT NOT NULL DEFAULT '', reason TEXT, state TEXT NOT NULL DEFAULT 'open', linked_requirements TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(linked_requirements)), principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE decisions(id TEXT PRIMARY KEY NOT NULL, statement TEXT NOT NULL DEFAULT '', reason TEXT, alternatives TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(alternatives)), state TEXT NOT NULL DEFAULT 'active', superseded_by TEXT REFERENCES decisions(id), principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE instructions(id TEXT PRIMARY KEY NOT NULL, literal_text TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 1, origin TEXT, state TEXT NOT NULL DEFAULT 'active', principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE project_log(id TEXT PRIMARY KEY NOT NULL, project_id TEXT REFERENCES projects(id), kind TEXT, text TEXT NOT NULL DEFAULT '', refs TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(refs)), principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE agent_profiles(id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL DEFAULT '', role TEXT, tools TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(tools)), model TEXT, budgets TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(budgets)), identity_document_id TEXT REFERENCES identity_docs(id), principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE agents(id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL DEFAULT '', description TEXT, profile_id TEXT REFERENCES agent_profiles(id), parent_id TEXT REFERENCES agents(id), level INTEGER NOT NULL DEFAULT 0, capability_token_ref TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE runs(id TEXT PRIMARY KEY NOT NULL, agent_id TEXT REFERENCES agents(id), task_id TEXT REFERENCES tasks(id), state TEXT NOT NULL DEFAULT 'pending', reason TEXT, paused_by TEXT, queue_position INTEGER, budget TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(budget)), consumption TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(consumption)), heartbeat_at INTEGER, last_progress_at INTEGER, instructions_rev_seen INTEGER NOT NULL DEFAULT 0, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE notifications(id TEXT PRIMARY KEY NOT NULL, task_id TEXT REFERENCES tasks(id), run_id TEXT REFERENCES runs(id), class TEXT NOT NULL DEFAULT 'normal', content TEXT NOT NULL DEFAULT '', attempted_channels TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(attempted_channels)), delivery_state TEXT NOT NULL DEFAULT 'pending', acknowledged_at INTEGER, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE client_messages(client_msg_id TEXT PRIMARY KEY NOT NULL, client_id TEXT NOT NULL, message_id TEXT NOT NULL REFERENCES messages(id), principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE journal(id TEXT PRIMARY KEY NOT NULL, run_id TEXT REFERENCES runs(id), sequence INTEGER NOT NULL, kind TEXT NOT NULL, payload TEXT, payload_blob TEXT REFERENCES blobs(hash), state TEXT NOT NULL DEFAULT 'pending', idempotency_key TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE agent_messages(id TEXT PRIMARY KEY NOT NULL, source_agent_id TEXT REFERENCES agents(id), destination_agent_id TEXT REFERENCES agents(id), kind TEXT, payload TEXT, priority INTEGER NOT NULL DEFAULT 0, delivered_at INTEGER, acknowledged_at INTEGER, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE leases(path TEXT PRIMARY KEY NOT NULL, holder_id TEXT NOT NULL, expires_at INTEGER NOT NULL, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE approvals(id TEXT PRIMARY KEY NOT NULL, run_id TEXT REFERENCES runs(id), content TEXT, extent TEXT, blocking INTEGER NOT NULL DEFAULT 1 CHECK(blocking IN (0,1)), default_value TEXT, deadline INTEGER, state TEXT NOT NULL DEFAULT 'pending', response TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE questions(id TEXT PRIMARY KEY NOT NULL, run_id TEXT REFERENCES runs(id), content TEXT, extent TEXT, blocking INTEGER NOT NULL DEFAULT 1 CHECK(blocking IN (0,1)), default_value TEXT, deadline INTEGER, state TEXT NOT NULL DEFAULT 'pending', response TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE capability_grants(id TEXT PRIMARY KEY NOT NULL, run_id TEXT REFERENCES runs(id), grant_definition TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(grant_definition)), extent TEXT, expires_at INTEGER, approval_id TEXT REFERENCES approvals(id), principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE memories(id TEXT PRIMARY KEY NOT NULL, kind TEXT, statement TEXT NOT NULL DEFAULT '', entities TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(entities)), valid_from INTEGER, valid_to INTEGER, recorded_at INTEGER NOT NULL DEFAULT (unixepoch()), expires_at INTEGER, state TEXT NOT NULL DEFAULT 'active', superseded_by TEXT REFERENCES memories(id), confidence REAL CHECK(confidence BETWEEN 0 AND 1), importance REAL, sources TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(sources)), source_confidence REAL CHECK(source_confidence BETWEEN 0 AND 1), usage_count INTEGER NOT NULL DEFAULT 0, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE entities(id TEXT PRIMARY KEY NOT NULL, kind TEXT, canonical_name TEXT NOT NULL DEFAULT '', aliases TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(aliases)), principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE relation_types(id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL DEFAULT '', description TEXT, domain TEXT, range TEXT, inverse_id TEXT REFERENCES relation_types(id), origin TEXT, usage_count INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'active', principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE edges(id TEXT PRIMARY KEY NOT NULL, layer TEXT NOT NULL CHECK(layer IN ('plan','memory','code','action')), source_type TEXT NOT NULL, source_id TEXT NOT NULL, relation_type TEXT NOT NULL, destination_type TEXT NOT NULL, destination_id TEXT NOT NULL, valid_from INTEGER, valid_to INTEGER, provenance TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE identity_docs(id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL DEFAULT '', content TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE doc_fragments(id TEXT PRIMARY KEY NOT NULL, document_id TEXT REFERENCES identity_docs(id), heading_path TEXT, ordinal INTEGER NOT NULL DEFAULT 0, text TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, hash TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE documents(id TEXT PRIMARY KEY NOT NULL, version INTEGER NOT NULL DEFAULT 1, blob_hash TEXT REFERENCES blobs(hash), kind TEXT, origin TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE doc_chunks(id TEXT PRIMARY KEY NOT NULL, document_id TEXT REFERENCES documents(id), page INTEGER, paragraph INTEGER, start_offset INTEGER, end_offset INTEGER, section TEXT, text TEXT NOT NULL DEFAULT '', principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE source_events(id TEXT PRIMARY KEY NOT NULL, run_id TEXT REFERENCES runs(id), search_id TEXT, url TEXT, title TEXT, observed_at INTEGER, hash TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE embedding_spaces(id TEXT PRIMARY KEY NOT NULL, model TEXT NOT NULL, dimensions INTEGER NOT NULL CHECK(dimensions > 0), quantization TEXT NOT NULL DEFAULT 'float32', state TEXT NOT NULL DEFAULT 'active', principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE skills(id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL DEFAULT '', manifest TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(manifest)), hash TEXT, state TEXT NOT NULL DEFAULT 'active', principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE skill_versions(id TEXT PRIMARY KEY NOT NULL, skill_id TEXT REFERENCES skills(id), version INTEGER NOT NULL, hash TEXT NOT NULL, content TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE skill_evals(id TEXT PRIMARY KEY NOT NULL, skill_version_id TEXT REFERENCES skill_versions(id), baseline_version_id TEXT REFERENCES skill_versions(id), definition TEXT, result TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE tool_packages(id TEXT PRIMARY KEY NOT NULL, manifest TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(manifest)), implementation_blob TEXT REFERENCES blobs(hash), tests TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE routines(id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL DEFAULT '', implementation TEXT, tests TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE schedules(id TEXT PRIMARY KEY NOT NULL, specification TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(specification)), next_run_at INTEGER, timezone TEXT NOT NULL DEFAULT 'UTC', missed_policy TEXT NOT NULL DEFAULT 'skip', principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE reminders(id TEXT PRIMARY KEY NOT NULL, schedule_id TEXT REFERENCES schedules(id), text TEXT NOT NULL DEFAULT '', next_run_at INTEGER, timezone TEXT NOT NULL DEFAULT 'UTC', state TEXT NOT NULL DEFAULT 'pending', principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE triggers(id TEXT PRIMARY KEY NOT NULL, rule TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(rule)), action TEXT, state TEXT NOT NULL DEFAULT 'active', principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE workflows(id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, definition TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(definition)), principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE workflow_runs(id TEXT PRIMARY KEY NOT NULL, workflow_id TEXT REFERENCES workflows(id), workflow_version INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'pending', position TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE policy_rules(id TEXT PRIMARY KEY NOT NULL, action TEXT NOT NULL, pattern TEXT NOT NULL, effect TEXT NOT NULL, extent TEXT, expires_at INTEGER, origin TEXT, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE secrets_meta(id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata)), encrypted_store_ref TEXT NOT NULL, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE audit(sequence INTEGER PRIMARY KEY AUTOINCREMENT, previous_hash TEXT, hash TEXT NOT NULL, redacted_event TEXT NOT NULL, principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE file_versions(id TEXT PRIMARY KEY NOT NULL, path TEXT NOT NULL, preimage_blob TEXT REFERENCES blobs(hash), postimage_blob TEXT REFERENCES blobs(hash), run_id TEXT REFERENCES runs(id), tool_call_id TEXT, recorded_at INTEGER NOT NULL DEFAULT (unixepoch()), principal_id TEXT REFERENCES principals(id), scope_id TEXT, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE blob_refs(owner_type TEXT NOT NULL, owner_id TEXT NOT NULL, slot TEXT NOT NULL DEFAULT '', hash TEXT NOT NULL REFERENCES blobs(hash), created_at INTEGER NOT NULL DEFAULT (unixepoch()), PRIMARY KEY(owner_type,owner_id,slot));
CREATE INDEX blob_refs_hash ON blob_refs(hash);
CREATE TRIGGER blob_refs_insert AFTER INSERT ON blob_refs BEGIN UPDATE blobs SET ref_count=ref_count+1 WHERE hash=NEW.hash; END;
CREATE TRIGGER blob_refs_delete AFTER DELETE ON blob_refs BEGIN UPDATE blobs SET ref_count=ref_count-1 WHERE hash=OLD.hash; END;
CREATE TRIGGER blob_refs_update AFTER UPDATE OF hash ON blob_refs WHEN OLD.hash<>NEW.hash BEGIN UPDATE blobs SET ref_count=ref_count-1 WHERE hash=OLD.hash; UPDATE blobs SET ref_count=ref_count+1 WHERE hash=NEW.hash; END;
CREATE TABLE short_codes(project_id TEXT NOT NULL, kind TEXT NOT NULL, next_value INTEGER NOT NULL CHECK(next_value>0), PRIMARY KEY(project_id,kind));
CREATE UNIQUE INDEX tasks_code ON tasks(project_id,code);
CREATE UNIQUE INDEX requirements_code ON requirements(project_id,code);
CREATE UNIQUE INDEX criteria_code ON criteria(requirement_id,code);
CREATE UNIQUE INDEX milestones_code ON milestones(project_id,code);
CREATE UNIQUE INDEX journal_sequence ON journal(run_id,sequence);
CREATE UNIQUE INDEX journal_idempotency ON journal(run_id,idempotency_key);
CREATE INDEX edges_source ON edges(layer,source_type,source_id);
CREATE INDEX edges_destination ON edges(layer,destination_type,destination_id);
CREATE VIRTUAL TABLE messages_fts USING fts5(text, content='messages', content_rowid='rowid', tokenize='unicode61');
CREATE TRIGGER messages_fts_insert AFTER INSERT ON messages BEGIN INSERT INTO messages_fts(rowid,text) VALUES(NEW.rowid,NEW.text); END;
CREATE TRIGGER messages_fts_delete AFTER DELETE ON messages BEGIN INSERT INTO messages_fts(messages_fts,rowid,text) VALUES('delete',OLD.rowid,OLD.text); END;
CREATE TRIGGER messages_fts_update AFTER UPDATE OF text ON messages BEGIN INSERT INTO messages_fts(messages_fts,rowid,text) VALUES('delete',OLD.rowid,OLD.text); INSERT INTO messages_fts(rowid,text) VALUES(NEW.rowid,NEW.text); END;
CREATE VIRTUAL TABLE memories_fts USING fts5(statement, content='memories', content_rowid='rowid', tokenize='unicode61');
CREATE TRIGGER memories_fts_insert AFTER INSERT ON memories BEGIN INSERT INTO memories_fts(rowid,statement) VALUES(NEW.rowid,NEW.statement); END;
CREATE TRIGGER memories_fts_delete AFTER DELETE ON memories BEGIN INSERT INTO memories_fts(memories_fts,rowid,statement) VALUES('delete',OLD.rowid,OLD.statement); END;
CREATE TRIGGER memories_fts_update AFTER UPDATE OF statement ON memories BEGIN INSERT INTO memories_fts(memories_fts,rowid,statement) VALUES('delete',OLD.rowid,OLD.statement); INSERT INTO memories_fts(rowid,statement) VALUES(NEW.rowid,NEW.statement); END;
CREATE VIRTUAL TABLE doc_fragments_fts USING fts5(text, content='doc_fragments', content_rowid='rowid', tokenize='unicode61');
CREATE TRIGGER doc_fragments_fts_insert AFTER INSERT ON doc_fragments BEGIN INSERT INTO doc_fragments_fts(rowid,text) VALUES(NEW.rowid,NEW.text); END;
CREATE TRIGGER doc_fragments_fts_delete AFTER DELETE ON doc_fragments BEGIN INSERT INTO doc_fragments_fts(doc_fragments_fts,rowid,text) VALUES('delete',OLD.rowid,OLD.text); END;
CREATE TRIGGER doc_fragments_fts_update AFTER UPDATE OF text ON doc_fragments BEGIN INSERT INTO doc_fragments_fts(doc_fragments_fts,rowid,text) VALUES('delete',OLD.rowid,OLD.text); INSERT INTO doc_fragments_fts(rowid,text) VALUES(NEW.rowid,NEW.text); END;
CREATE VIRTUAL TABLE doc_chunks_fts USING fts5(text, content='doc_chunks', content_rowid='rowid', tokenize='unicode61');
CREATE TRIGGER doc_chunks_fts_insert AFTER INSERT ON doc_chunks BEGIN INSERT INTO doc_chunks_fts(rowid,text) VALUES(NEW.rowid,NEW.text); END;
CREATE TRIGGER doc_chunks_fts_delete AFTER DELETE ON doc_chunks BEGIN INSERT INTO doc_chunks_fts(doc_chunks_fts,rowid,text) VALUES('delete',OLD.rowid,OLD.text); END;
CREATE TRIGGER doc_chunks_fts_update AFTER UPDATE OF text ON doc_chunks BEGIN INSERT INTO doc_chunks_fts(doc_chunks_fts,rowid,text) VALUES('delete',OLD.rowid,OLD.text); INSERT INTO doc_chunks_fts(rowid,text) VALUES(NEW.rowid,NEW.text); END;
CREATE TRIGGER documents_blob_hash_ref_insert AFTER INSERT ON documents WHEN NEW.blob_hash IS NOT NULL BEGIN INSERT INTO blob_refs(owner_type,owner_id,slot,hash) VALUES('documents',NEW.id,'blob_hash',NEW.blob_hash); END;
CREATE TRIGGER documents_blob_hash_ref_delete AFTER DELETE ON documents BEGIN DELETE FROM blob_refs WHERE owner_type='documents' AND owner_id=OLD.id AND slot='blob_hash'; END;
CREATE TRIGGER documents_blob_hash_ref_update AFTER UPDATE OF blob_hash ON documents BEGIN DELETE FROM blob_refs WHERE owner_type='documents' AND owner_id=OLD.id AND slot='blob_hash'; INSERT INTO blob_refs(owner_type,owner_id,slot,hash) SELECT 'documents',NEW.id,'blob_hash',NEW.blob_hash WHERE NEW.blob_hash IS NOT NULL; END;
CREATE TRIGGER evidence_output_blob_ref_insert AFTER INSERT ON evidence WHEN NEW.output_blob IS NOT NULL BEGIN INSERT INTO blob_refs(owner_type,owner_id,slot,hash) VALUES('evidence',NEW.id,'output_blob',NEW.output_blob); END;
CREATE TRIGGER evidence_output_blob_ref_delete AFTER DELETE ON evidence BEGIN DELETE FROM blob_refs WHERE owner_type='evidence' AND owner_id=OLD.id AND slot='output_blob'; END;
CREATE TRIGGER evidence_output_blob_ref_update AFTER UPDATE OF output_blob ON evidence BEGIN DELETE FROM blob_refs WHERE owner_type='evidence' AND owner_id=OLD.id AND slot='output_blob'; INSERT INTO blob_refs(owner_type,owner_id,slot,hash) SELECT 'evidence',NEW.id,'output_blob',NEW.output_blob WHERE NEW.output_blob IS NOT NULL; END;
CREATE TRIGGER journal_payload_blob_ref_insert AFTER INSERT ON journal WHEN NEW.payload_blob IS NOT NULL BEGIN INSERT INTO blob_refs(owner_type,owner_id,slot,hash) VALUES('journal',NEW.id,'payload_blob',NEW.payload_blob); END;
CREATE TRIGGER journal_payload_blob_ref_delete AFTER DELETE ON journal BEGIN DELETE FROM blob_refs WHERE owner_type='journal' AND owner_id=OLD.id AND slot='payload_blob'; END;
CREATE TRIGGER journal_payload_blob_ref_update AFTER UPDATE OF payload_blob ON journal BEGIN DELETE FROM blob_refs WHERE owner_type='journal' AND owner_id=OLD.id AND slot='payload_blob'; INSERT INTO blob_refs(owner_type,owner_id,slot,hash) SELECT 'journal',NEW.id,'payload_blob',NEW.payload_blob WHERE NEW.payload_blob IS NOT NULL; END;
CREATE TRIGGER file_versions_preimage_blob_ref_insert AFTER INSERT ON file_versions WHEN NEW.preimage_blob IS NOT NULL BEGIN INSERT INTO blob_refs(owner_type,owner_id,slot,hash) VALUES('file_versions',NEW.id,'preimage_blob',NEW.preimage_blob); END;
CREATE TRIGGER file_versions_preimage_blob_ref_delete AFTER DELETE ON file_versions BEGIN DELETE FROM blob_refs WHERE owner_type='file_versions' AND owner_id=OLD.id AND slot='preimage_blob'; END;
CREATE TRIGGER file_versions_preimage_blob_ref_update AFTER UPDATE OF preimage_blob ON file_versions BEGIN DELETE FROM blob_refs WHERE owner_type='file_versions' AND owner_id=OLD.id AND slot='preimage_blob'; INSERT INTO blob_refs(owner_type,owner_id,slot,hash) SELECT 'file_versions',NEW.id,'preimage_blob',NEW.preimage_blob WHERE NEW.preimage_blob IS NOT NULL; END;
CREATE TRIGGER file_versions_postimage_blob_ref_insert AFTER INSERT ON file_versions WHEN NEW.postimage_blob IS NOT NULL BEGIN INSERT INTO blob_refs(owner_type,owner_id,slot,hash) VALUES('file_versions',NEW.id,'postimage_blob',NEW.postimage_blob); END;
CREATE TRIGGER file_versions_postimage_blob_ref_delete AFTER DELETE ON file_versions BEGIN DELETE FROM blob_refs WHERE owner_type='file_versions' AND owner_id=OLD.id AND slot='postimage_blob'; END;
CREATE TRIGGER file_versions_postimage_blob_ref_update AFTER UPDATE OF postimage_blob ON file_versions BEGIN DELETE FROM blob_refs WHERE owner_type='file_versions' AND owner_id=OLD.id AND slot='postimage_blob'; INSERT INTO blob_refs(owner_type,owner_id,slot,hash) SELECT 'file_versions',NEW.id,'postimage_blob',NEW.postimage_blob WHERE NEW.postimage_blob IS NOT NULL; END;
CREATE TRIGGER tool_packages_implementation_blob_ref_insert AFTER INSERT ON tool_packages WHEN NEW.implementation_blob IS NOT NULL BEGIN INSERT INTO blob_refs(owner_type,owner_id,slot,hash) VALUES('tool_packages',NEW.id,'implementation_blob',NEW.implementation_blob); END;
CREATE TRIGGER tool_packages_implementation_blob_ref_delete AFTER DELETE ON tool_packages BEGIN DELETE FROM blob_refs WHERE owner_type='tool_packages' AND owner_id=OLD.id AND slot='implementation_blob'; END;
CREATE TRIGGER tool_packages_implementation_blob_ref_update AFTER UPDATE OF implementation_blob ON tool_packages BEGIN DELETE FROM blob_refs WHERE owner_type='tool_packages' AND owner_id=OLD.id AND slot='implementation_blob'; INSERT INTO blob_refs(owner_type,owner_id,slot,hash) SELECT 'tool_packages',NEW.id,'implementation_blob',NEW.implementation_blob WHERE NEW.implementation_blob IS NOT NULL; END;
-- Attachments are an ordered JSON array of SHA-256 hashes; metadata belongs to the owner.
CREATE TRIGGER messages_attachments_insert AFTER INSERT ON messages BEGIN
  INSERT INTO blob_refs(owner_type,owner_id,slot,hash) SELECT 'messages',NEW.id,'attachment:'||key,value FROM json_each(NEW.attachments);
END;
CREATE TRIGGER messages_attachments_delete AFTER DELETE ON messages BEGIN
  DELETE FROM blob_refs WHERE owner_type='messages' AND owner_id=OLD.id AND slot LIKE 'attachment:%';
END;
CREATE TRIGGER messages_attachments_update AFTER UPDATE OF attachments ON messages BEGIN
  DELETE FROM blob_refs WHERE owner_type='messages' AND owner_id=OLD.id AND slot LIKE 'attachment:%';
  INSERT INTO blob_refs(owner_type,owner_id,slot,hash) SELECT 'messages',NEW.id,'attachment:'||key,value FROM json_each(NEW.attachments);
END;
